"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { MoreHorizontal } from "lucide-react"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { cn } from "@/lib/utils"
import { joinMeta } from "@/lib/dashboard-format"
import { PriorityBadge, type PriorityLevel } from "@/components/ui/priority-badge"

export type RecordCrumb = { label: string; href?: string; onSelect?: () => void }

export type RecordPerson = { name: string; src?: string }

export type RecordAction = { id: string; label: string; onSelect: () => void }

export type RecordHeaderClassNames = {
  root?: string
  title?: string
  meta?: string
  actions?: string
}

export type RecordHeaderProps = {
  crumbs?: readonly RecordCrumb[]
  title: string
  headingLevel?: 1 | 2 | 3
  status?: string
  meta?: readonly string[]
  people?: readonly RecordPerson[]
  priority?: PriorityLevel
  priorityLabel?: string
  statusDot?: string
  primary?: React.ReactNode
  secondary?: readonly RecordAction[]
  menu?: readonly RecordAction[]
  collapseActions?: boolean
  aside?: React.ReactNode
  className?: string
  classNames?: RecordHeaderClassNames
}

function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

function CrumbLink({ crumb }: { crumb: RecordCrumb }) {
  if (crumb.href) {
    return (
      <BreadcrumbLink
        href={crumb.href}
        onClick={(event) => {
          if (!crumb.onSelect) return
          event.preventDefault()
          crumb.onSelect()
        }}
      >
        {crumb.label}
      </BreadcrumbLink>
    )
  }
  return (
    <button type="button" className="hover:text-foreground" onClick={crumb.onSelect}>
      {crumb.label}
    </button>
  )
}

export function RecordHeader({
  crumbs = [],
  title,
  headingLevel = 1,
  status,
  meta = [],
  people = [],
  priority,
  priorityLabel,
  statusDot,
  primary,
  secondary = [],
  menu = [],
  collapseActions = true,
  aside,
  className,
  classNames,
}: RecordHeaderProps) {
  const rootRef = React.useRef<HTMLElement>(null)
  const [narrow, setNarrow] = React.useState(false)
  React.useEffect(() => {
    const node = rootRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver((entries) => {
      setNarrow((entries[0]?.contentRect.width ?? 0) < 400)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])
  const Heading = `h${headingLevel}` as "h1" | "h2" | "h3"
  const middle = crumbs.length > 2 ? crumbs.slice(1, -1) : []
  const foldSecondary = collapseActions && narrow
  const menuActions = [...menu, ...(foldSecondary ? secondary : [])]
  return (
    <header ref={rootRef} data-slot="record-header" className={cn("@container min-w-0", className, classNames?.root)}>
      {crumbs.length ? (
        <Breadcrumb>
          <BreadcrumbList>
            <BreadcrumbItem>
              {crumbs[0]?.href || crumbs[0]?.onSelect ? <CrumbLink crumb={crumbs[0]} /> : <span>{crumbs[0]?.label}</span>}
            </BreadcrumbItem>
            {middle.length ? (
              <>
                <BreadcrumbSeparator />
                <BreadcrumbItem className="@max-[30rem]:hidden">
                  <span className="inline-flex flex-wrap items-center gap-1.5">
                    {middle.map((crumb) => (
                      <span key={crumb.label} className="inline-flex items-center gap-1.5">
                        <CrumbLink crumb={crumb} />
                        <span aria-hidden>/</span>
                      </span>
                    ))}
                  </span>
                </BreadcrumbItem>
                <BreadcrumbItem className="hidden @max-[30rem]:inline-flex">
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button type="button" variant="ghost" size="icon-sm" aria-label="More breadcrumbs">
                        <MoreHorizontal />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent>
                      {middle.map((crumb) => (
                        <DropdownMenuItem key={crumb.label} onSelect={() => crumb.onSelect?.()}>
                          {crumb.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </BreadcrumbItem>
              </>
            ) : null}
            {crumbs.length > 1 ? (
              <>
                <BreadcrumbSeparator />
                <BreadcrumbItem>
                  <BreadcrumbPage className="break-words">{crumbs[crumbs.length - 1]?.label}</BreadcrumbPage>
                </BreadcrumbItem>
              </>
            ) : null}
          </BreadcrumbList>
        </Breadcrumb>
      ) : null}
      <div className="mt-2 flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <Heading className={cn("m-0 text-3xl font-normal tracking-tight break-words", classNames?.title)}>{title}</Heading>
            {status ? <span className="inline-flex h-6 items-center rounded-full bg-chart-2/20 px-2 text-xs">{status}</span> : null}
          </div>
          {meta.length ? <p className={cn("mt-1 text-sm text-muted-foreground break-words", classNames?.meta)}>{joinMeta([...meta])}</p> : null}
          {people.length || priority || statusDot ? (
            <div className="mt-2 flex flex-wrap items-center gap-2">
              {people.length ? (
                <span className="inline-flex items-center">
                  {people.map((person, index) => (
                    <Avatar key={person.name} size="sm" className={cn(index > 0 && "-ms-2 ring-2 ring-background")}>
                      {person.src ? <AvatarImage src={person.src} alt="" /> : null}
                      <AvatarFallback>{initials(person.name)}</AvatarFallback>
                    </Avatar>
                  ))}
                  <span className="ms-2 text-xs text-muted-foreground">{people.map((person) => person.name).join(", ")}</span>
                </span>
              ) : null}
              {priority ? <PriorityBadge level={priority} label={priorityLabel} /> : null}
              {statusDot ? (
                <span className="inline-flex items-center gap-1 text-xs text-muted-foreground">
                  <span className="size-2 rounded-full bg-chart-2" aria-hidden />
                  {statusDot}
                </span>
              ) : null}
            </div>
          ) : null}
        </div>
        <div className={cn("flex flex-wrap items-center gap-2", classNames?.actions)}>
          {aside}
          {menuActions.length ? (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button type="button" variant="ghost" size="icon" className="rounded-full" aria-label="More actions">
                  <MoreHorizontal />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                {menuActions.map((action) => (
                  <DropdownMenuItem key={action.id} onSelect={() => action.onSelect()}>
                    {action.label}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          ) : null}
          {foldSecondary ? null : (
            <div className="flex flex-wrap gap-2">
              {secondary.map((action) => (
                <Button key={action.id} type="button" variant="secondary" className="rounded-full bg-muted" onClick={action.onSelect}>
                  {action.label}
                </Button>
              ))}
            </div>
          )}
          {primary}
        </div>
      </div>
    </header>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"

export const PRIORITY_LEVELS = ["low", "medium", "high", "critical"] as const

export type PriorityLevel = (typeof PRIORITY_LEVELS)[number]

export type PriorityBadgeClassNames = {
  root?: string
  glyph?: string
  label?: string
}

export type PriorityBadgeProps = {
  level: PriorityLevel
  label?: string
  variant?: "chip" | "glyph"
  className?: string
  classNames?: PriorityBadgeClassNames
}

const DEFAULT_LABEL: Record<PriorityLevel, string> = {
  low: "Low",
  medium: "Medium",
  high: "High",
  critical: "Critical",
}

export function priorityRank(level: PriorityLevel): number {
  return PRIORITY_LEVELS.indexOf(level) + 1
}

export function comparePriority(a: PriorityLevel, b: PriorityLevel): number {
  return priorityRank(a) - priorityRank(b)
}

function SignalGlyph({ filled, className }: { filled: number; className?: string }) {
  const heights = [4, 7, 10, 13]
  return (
    <svg viewBox="0 0 16 14" className={cn("h-3.5 w-4", className)} aria-hidden>
      {heights.map((height, index) => (
        <rect
          key={height}
          x={index * 4}
          y={14 - height}
          width="2.5"
          height={height}
          rx="0.5"
          className={index < filled ? "fill-current" : "fill-current opacity-30"}
        />
      ))}
    </svg>
  )
}

export function PriorityBadge({
  level,
  label,
  variant = "chip",
  className,
  classNames,
}: PriorityBadgeProps) {
  const text = label ?? DEFAULT_LABEL[level]
  const critical = level === "critical"
  if (variant === "glyph") {
    return (
      <span className={cn("inline-flex text-foreground", critical && "text-destructive", className, classNames?.root)} aria-label={text}>
        <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      </span>
    )
  }
  return (
    <span
      data-slot="priority-badge"
      data-level={level}
      className={cn(
        "inline-flex h-6 max-w-full items-center gap-1 rounded-full px-2 text-xs font-medium",
        critical ? "bg-destructive/10 text-destructive" : "bg-muted text-foreground",
        className,
        classNames?.root,
      )}
    >
      <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      <span className={cn("truncate", classNames?.label)}>{text}</span>
    </span>
  )
}

/** Number, date, and greeting helpers for dashboard pieces. No theme tokens. */

export type DashboardFormat = "number" | "currency" | "percent" | "compact" | "text" | "points"

export function formatDashboardValue(
  value: number | string,
  format: DashboardFormat = "text",
  locale = "en-US",
  currency = "USD",
): string {
  if (typeof value !== "number" || !Number.isFinite(value) || format === "text") return String(value)
  if (format === "currency") {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      notation: Math.abs(value) >= 10000 ? "compact" : "standard",
      maximumFractionDigits: Math.abs(value) >= 10000 ? 1 : 0,
    }).format(value)
  }
  if (format === "percent") {
    return new Intl.NumberFormat(locale, {
      style: "percent",
      maximumFractionDigits: 1,
    }).format(value)
  }
  if (format === "compact") {
    return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value)
  }
  if (format === "points") {
    const formatted = new Intl.NumberFormat(locale, {
      signDisplay: "exceptZero",
      maximumFractionDigits: 1,
    }).format(value)
    return `${formatted} pts`
  }
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)
}

export function formatDashboardDate(
  value: string | number | Date,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { month: "short", day: "numeric" },
): string {
  const date = value instanceof Date ? value : new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return new Intl.DateTimeFormat(locale, options).format(date)
}

export function joinMeta(parts: Array<string | number | null | undefined | false>): string {
  return parts.filter((part) => part != null && part !== false && part !== "").map(String).join(" · ")
}

const DAY_PART = {
  en: { morning: "Good morning", afternoon: "Good afternoon", evening: "Good evening" },
  es: { morning: "Buenos días", afternoon: "Buenas tardes", evening: "Buenas noches" },
} as const

/** Time-of-day greeting. Spanish locales use es; everything else uses en. */
export function greeting(date: Date, locale: string, name: string): string {
  const hour = date.getHours()
  const part = hour < 12 ? "morning" : hour < 18 ? "afternoon" : "evening"
  const table = locale.toLowerCase().startsWith("es") ? DAY_PART.es : DAY_PART.en
  return `${table[part]}, ${name}`
}

export function shareOf(value: number, total: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(total) || total <= 0) return 0
  return value / total
}

export function clampRatio(value: number, min: number, max: number): number {
  const span = max - min
  if (!Number.isFinite(span) || span <= 0) return 0
  return Math.min(1, Math.max(0, (value - min) / span))
}

export type RankedInput = { id: string; value: number; share?: number }

export function orderRanked<T extends RankedInput>(items: readonly T[], sort: "asc" | "desc" | "none" = "desc"): T[] {
  const copy = items.map((item) => ({ ...item }))
  if (sort === "asc") copy.sort((a, b) => a.value - b.value || a.id.localeCompare(b.id))
  if (sort === "desc") copy.sort((a, b) => b.value - a.value || a.id.localeCompare(b.id))
  const total = copy.reduce((sum, item) => sum + (Number.isFinite(item.value) ? item.value : 0), 0)
  return copy.map((item) => ({ ...item, share: item.share ?? shareOf(item.value, total) }))
}

/** Delay in seconds for a short opacity stagger. Zero when motion is reduced. */
export function staggerDelay(index: number, reduced: boolean, step = 0.04): number {
  if (reduced || index <= 0) return 0
  return index * step
}
